'use client';

import { useState, useTransition } from 'react';
import { Plus } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
  DialogClose,
} from '@/components/ui/dialog';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useToast } from '@/hooks/use-toast';
import { Loader2 } from 'lucide-react';
import { addTab } from '@/app/actions';

const AddTabSchema = z.object({
  tabName: z.string().min(1, 'Tab name is required.'),
});

type AddTabFormValues = z.infer<typeof AddTabSchema>;

type AddTabDialogProps = {
  toolId: string;
};

export function AddTabDialog({ toolId }: AddTabDialogProps) {
  const [open, setOpen] = useState(false);
  const [isPending, startTransition] = useTransition();
  const { toast } = useToast();

  const form = useForm<AddTabFormValues>({
    resolver: zodResolver(AddTabSchema),
    defaultValues: {
      tabName: '',
    },
  });

  const onSubmit = async (values: AddTabFormValues) => {
    startTransition(async () => {
      try {
        const result = await addTab(toolId, values.tabName);

        if (result.success) {
          toast({
            title: 'Tab Created!',
            description: `The tab "${values.tabName}" has been added.`,
          });
          setOpen(false);
          form.reset();
        } else {
          throw new Error(result.error);
        }
      } catch (error) {
        console.error('Failed to create new tab:', error);
        toast({
          variant: 'destructive',
          title: 'Error',
          description:
            error instanceof Error
              ? error.message
              : 'Failed to create new tab. Please try again.',
        });
      }
    });
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="icon" className="h-8 w-8 shrink-0">
          <Plus className="h-4 w-4" />
          <span className="sr-only">Add Tab</span>
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Add a New Tab</DialogTitle>
          <DialogDescription>
            Enter a name for your new tab. A new tab will be created with a default editor panel.
          </DialogDescription>
        </DialogHeader>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="tabName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Tab Name</FormLabel>
                  <FormControl>
                    <Input placeholder="e.g., 'Chapter 2'" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <DialogFooter>
                <DialogClose asChild>
                    <Button variant="ghost">Cancel</Button>
                </DialogClose>
                <Button type="submit" disabled={isPending}>
                {isPending && <Loader2 className="mr-2 animate-spin" />}
                Add Tab
              </Button>
            </DialogFooter>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}
